"""Official task state is committed on main; task branches contain the work."""
from contextlib import contextmanager
from contextvars import ContextVar
import fnmatch
import json
import os
from pathlib import Path, PurePosixPath
import stat
import subprocess
from typing import NamedTuple

import task_evidence as proof
from task_model import TaskError, new_task, parse_task, render_task, task_path, valid_sha, validate_transition
from validate_contracts import parse_frontmatter, validate_file


_OBJECT_CACHE = ContextVar('kdd_git_objects', default=None)


class _MutationContext(NamedTuple):
    head: str
    options: dict


class _PerimeterContext(NamedTuple):
    base: str
    tip: str
    tested: str


@contextmanager
def object_cache():
    if _OBJECT_CACHE.get() is not None:
        yield
        return
    token = _OBJECT_CACHE.set({})
    try:
        yield
    finally:
        _OBJECT_CACHE.reset(token)


def _key(root, kind, revision, *parts):
    return (str(Path(root).resolve()), kind, revision, *parts)


def _output(root, args):
    try:
        result = subprocess.run(['git', '--literal-pathspecs', '-C', str(root), *args],
                                capture_output=True, text=True, encoding='utf-8', timeout=30)
    except (OSError, UnicodeError, subprocess.SubprocessError) as exc:
        raise TaskError('TASK_GIT: ' + str(exc)) from exc
    if result.returncode:
        raise TaskError('TASK_GIT: ' + result.stderr.strip())
    return result.stdout


def git(root, *args):
    return _output(root, args).strip()


def _native_oid(root, ref):
    if not valid_sha(ref):
        return False
    cache = _OBJECT_CACHE.get()
    key = _key(root, 'object-format', '')
    try:
        if cache is not None and key in cache:
            algorithm = cache[key]
        else:
            algorithm = git(root, 'rev-parse', '--show-object-format')
            if cache is not None:
                cache[key] = algorithm
    except TaskError:
        return False
    return len(ref) == {'sha1': 40, 'sha256': 64}.get(algorithm)


def _commit_with_uninitialized_format(root, ref, cache, key):
    format_key = _key(root, 'object-format', '')
    try:
        fields = git(root, 'rev-parse', '--show-object-format', '--verify',
                     '--end-of-options', ref + '^{commit}').splitlines()
    except TaskError:
        fields = []
    if (len(fields) == 2 and valid_sha(fields[1])
            and len(fields[1]) == {'sha1': 40, 'sha256': 64}.get(fields[0])):
        cache[format_key] = fields[0]
        if valid_sha(ref) and len(ref) == len(fields[1]):
            cache[key] = fields[1]
        return fields[1]
    return git(root, 'rev-parse', '--verify', '--end-of-options', ref + '^{commit}')


def commit_sha(root, ref):
    cache = _OBJECT_CACHE.get()
    if cache is None:
        return git(root, 'rev-parse', '--verify', '--end-of-options', ref + '^{commit}')
    key = _key(root, 'commit', ref)
    if _key(root, 'object-format', '') not in cache:
        return _commit_with_uninitialized_format(root, ref, cache, key)
    immutable = _native_oid(root, ref)
    if cache is not None and immutable and key in cache:
        return cache[key]
    revision = git(root, 'rev-parse', '--verify', '--end-of-options', ref + '^{commit}')
    if cache is not None and immutable:
        cache[key] = revision
    return revision


def blob(root, ref, path):
    return blobs(root, ref, [path])[path]


def _batch_blobs(root, revision, names):
    specifications = [revision + ':' + name for name in names]
    if any(any(c in spec for c in '\r\n\0') for spec in specifications):
        raise TaskError('TASK_PATH: invalid batch object path')
    try:
        result = subprocess.run(['git', '-C', str(root), 'cat-file', '--batch'],
                                input=('\n'.join(specifications) + '\n').encode('utf-8'),
                                capture_output=True, timeout=30, check=False)
        if result.returncode:
            raise TaskError('TASK_GIT: batch read failed')
        offset, values = 0, {}
        for name in names:
            end = result.stdout.find(b'\n', offset)
            header = result.stdout[offset:end].split() if end >= 0 else []
            if (len(header) != 3 or header[1] != b'blob' or not header[2].isdigit()
                    or not valid_sha(header[0].decode('ascii'))):
                raise TaskError('TASK_GIT: missing or invalid blob: ' + name)
            size, offset = int(header[2]), end + 1
            if result.stdout[offset + size:offset + size + 1] != b'\n':
                raise TaskError('TASK_GIT: truncated batch blob')
            value = result.stdout[offset:offset + size].decode('utf-8')
            values[name] = value.replace('\r\n', '\n').replace('\r', '\n')
            offset += size + 1
        if offset != len(result.stdout):
            raise TaskError('TASK_GIT: unexpected batch output')
        return values
    except (OSError, UnicodeError, subprocess.SubprocessError) as exc:
        raise TaskError('TASK_GIT: ' + str(exc)) from exc


def _reuse_cached_blob_objects(root, revision, names, cache):
    for name in names:
        key = _key(root, 'blob', revision, name)
        oid = cache.get(_key(root, 'regular-path', revision, name))
        content_key = _key(root, 'blob-object', oid)
        if key not in cache and oid and content_key in cache:
            cache[key] = cache[content_key]


def _remember_blob_objects(root, revision, values, cache):
    for name, value in values.items():
        cache[_key(root, 'blob', revision, name)] = value
        oid = cache.get(_key(root, 'regular-path', revision, name))
        if oid:
            cache[_key(root, 'blob-object', oid)] = value


def blobs(root, ref, names):
    if not names:
        return {}
    revision = ref if _native_oid(root, ref) else commit_sha(root, ref)
    cache = _OBJECT_CACHE.get()
    names = list(dict.fromkeys(names))
    if cache is not None:
        _reuse_cached_blob_objects(root, revision, names, cache)
    missing = [name for name in names if cache is None or _key(root, 'blob', revision, name) not in cache]
    values = _batch_blobs(root, revision, missing) if missing else {}
    if cache is not None:
        _remember_blob_objects(root, revision, values, cache)
        return {name: cache[_key(root, 'blob', revision, name)] for name in names}
    return values


def paths(root, ref, directory):
    cache = _OBJECT_CACHE.get()
    key = _key(root, 'paths', ref, directory)
    immutable = cache is not None and _native_oid(root, ref)
    if cache is not None and immutable and key in cache:
        return list(cache[key])
    output = git(root, 'ls-tree', '-r', '--name-only', '-z', ref, '--', directory)
    result = sorted(filter(None, output.split('\0')))
    if cache is not None and immutable:
        cache[key] = tuple(result)
    return result


def _ancestor_key(root, before, after, cache):
    if cache is not None and _native_oid(root, before) and _native_oid(root, after):
        return _key(root, 'ancestor', before, after)
    return None


def ancestor(root, before, after):
    cache = _OBJECT_CACHE.get()
    key = _ancestor_key(root, before, after, cache)
    if cache is not None and key is not None and key in cache:
        return True
    try:
        git(root, 'merge-base', '--is-ancestor', before, after)
        if cache is not None and key is not None:
            cache[key] = True
        return True
    except TaskError:
        return False


def _relative_parts(relative):
    parts = PurePosixPath(relative).parts
    if not parts or relative.startswith('/') or any(p in ('.', '..') for p in parts):
        raise TaskError('TASK_PATH: exact relative path required')
    if any(c in relative for c in '\\:\0'):
        raise TaskError('TASK_PATH: invalid path')
    return parts


def safe_path(root, relative):
    parts = _relative_parts(relative)
    path = Path(root).joinpath(*parts)
    component = Path(root)
    for index, part in enumerate(parts):
        component = component / part
        try:
            info = component.lstat()
        except FileNotFoundError:
            break
        if stat.S_ISLNK(info.st_mode) or getattr(info, 'st_file_attributes', 0) & 0x400:
            raise TaskError('TASK_PATH: symlinks and reparse points are not supported')
        if index < len(parts) - 1:
            if not stat.S_ISDIR(info.st_mode):
                raise TaskError('TASK_PATH: ancestor must be a directory')
        elif not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
            raise TaskError('TASK_PATH: expected a regular file with one hardlink')
    if not path.resolve().is_relative_to(Path(root).resolve()):
        raise TaskError('TASK_PATH: path escapes repository')
    return path

"""Validate committed Task snapshots and every mainline transition read-only."""
import argparse
import json
from pathlib import Path
import sys

import task_evidence as proof
import task_git as journal
from task_model import TaskError, task_path, valid_sha, validate_transition
from validate_contracts import parse_frontmatter


def _dependencies(tasks):
    errors = []
    visited = set()
    def visit(identifier, active):
        if identifier not in tasks:
            errors.append('TASK_DEPENDENCIES: missing ' + identifier)
            return
        if identifier in active:
            errors.append('TASK_DEPENDENCIES: dependency cycle at ' + identifier)
            return
        if identifier not in visited:
            for dependency in tasks[identifier]['depends_on']:
                visit(dependency, active | {identifier})
            visited.add(identifier)
    for identifier in tasks:
        visit(identifier, set())
    return errors


def _proof_output(report, metadata):
    _, runner = proof.invocation(metadata)
    valid = (report.get('runner') == runner and type(report.get('exit_code')) is int
             and report['exit_code'] == 0 and type(report.get('passed_tests')) is int)
    if not valid or not all(isinstance(report.get(k), str) for k in ('stdout', 'stderr')):
        return ['TASK_EVIDENCE: invalid runner result']
    expected = proof.passed_tests(runner, report['stdout'], report['stderr'])
    if expected < 1 or report['passed_tests'] != expected:
        return ['TASK_EVIDENCE: missing recognized passing tests']
    if report.get('output_sha256') != proof.digest(report['stdout'] + report['stderr']):
        return ['TASK_EVIDENCE: output digest mismatch']
    return []


def _proof_refs(root, task, report):
    tip = report.get('branch_tip')
    if not valid_sha(tip) or tip == task['branch_base']:
        return ['TASK_EVIDENCE: missing implementation tip']
    pairs = [(task['branch_base'], tip), (tip, task['verified_ref'])]
    if not all(journal.ancestor(root, a, b) for a, b in pairs):
        return ['TASK_EVIDENCE: implementation is not integrated']
    return []


def _proof_fields(root, task, report, metadata):
    expected = {'schema_version': 1, 'task_id': task['task_id'],
                'tested_commit': task['verified_ref'], 'approved_ref': task['approved_ref'],
                'command': metadata['test_command']}
    for field, path in [('contract_sha256', task['contract']),
                        ('target_sha256', metadata['target']), ('oracle_sha256', metadata['tests'])]:
        expected[field] = proof.digest(proof.normalized(journal.blob(root, task['verified_ref'], path)))
    return ['TASK_EVIDENCE: mismatch in ' + k for k, v in expected.items() if report.get(k) != v]


def _proof_perimeter(root, task, report):
    expected = journal.task_perimeter(root, task, task['verified_ref'], report['branch_tip'])
    if 'perimeter' in report and report['perimeter'] != expected:
        return ['TASK_PERIMETER: receipt differs from Git: ' +
                json.dumps(report['perimeter'], sort_keys=True)]
    return []


def _evidence(root, ref, task, metadata):
    content = journal.blob(root, ref, task['evidence'])
    if proof.digest(content) != task['evidence_sha256']:
        return ['TASK_EVIDENCE: artifact digest mismatch']
    report = json.loads(content)
    if not isinstance(report, dict):
        return ['TASK_EVIDENCE: expected an object']
    if not journal.ancestor(root, task['verified_ref'], journal.commit_sha(root, ref)):
        return ['TASK_EVIDENCE: tested commit is not an ancestor']
    findings = (_proof_fields(root, task, report, metadata) + _proof_refs(root, task, report)
                + _proof_output(report, metadata))
    return findings or _proof_perimeter(root, task, report)


def _snapshot(repo_root, ref='main'):
    root = Path(repo_root).resolve()
    try:
        revision = journal.commit_sha(root, ref)
        tasks = journal.read_tasks(root, revision)
        errors = _dependencies(tasks)
        for task in tasks.values():
            if task['status'] == 'backlog':
                metadata, _ = parse_frontmatter(journal.blob(root, revision, task['contract']))
                if not isinstance(metadata, dict) or metadata.get('type') != 'Task Contract':
                    errors.append('TASK_CONTRACT: linked contract is not a Task Contract')
                continue
            tested = task['verified_ref'] if task['status'] == 'done' else revision
            metadata = journal.contract_metadata(root, task, tested, committed_only=True)
            if task['status'] == 'done':
                errors.extend(_evidence(root, revision, task, metadata))
        return errors
    except (TaskError, ValueError, OSError, KeyError) as exc:
        return ['TASK_SNAPSHOT: ' + str(exc)]


def validate_snapshot(repo_root, ref='main'):
    with journal.object_cache():
        return _snapshot(repo_root, ref)


def _transition_scope(old, new, identifier, parent):
    errors, allowed = [], {task_path(identifier)}
    if old is None:
        allowed.add('knowledge/index.md')
    if new and new['status'] == 'done':
        allowed.add(new['evidence'])
        if new['verified_ref'] != parent:
            errors.append('TASK_CLOSURE: tested commit must be the immediate parent')
    if old and not old['branch_base'] and new and new['status'] == 'in_progress':
        if new['branch_base'] != parent:
            errors.append('TASK_BRANCH: initial branch base must be the start parent')
    return errors, allowed


def _audit_import(root, parents, nodes, changed, cache):
    if len(parents) != 2:
        return ['TASK_IMPORT: only two-parent journal imports are supported']
    bases = journal.git(root, 'merge-base', '--all', *parents).splitlines()
    if len(bases) != 1:
        return ['TASK_IMPORT: journal import requires an unambiguous fork']
    fork, source = journal.read_nodes(root, bases[0]), journal.read_nodes(root, parents[1])
    before, after = nodes
    errors = []
    for identifier in changed:
        if before.get(identifier) != fork.get(identifier):
            errors.append('TASK_IMPORT: concurrent target change to ' + identifier)
        if identifier not in source or after.get(identifier) != source.get(identifier):
            errors.append('TASK_IMPORT: merge must preserve the source node ' + identifier)
    return errors + _audit_range(root, bases[0], parents[1], cache)


def _audit_commit(root, parent, revision, cache, parents):
    before, after = journal.read_nodes(root, parent), journal.read_nodes(root, revision)
    changed = [key for key in sorted(before.keys() | after.keys()) if before.get(key) != after.get(key)]
    if len(parents) > 1:
        errors = _audit_import(root, parents, (before, after), changed, cache)
        return errors + ['{}: {}'.format(revision, e) for e in validate_snapshot(root, revision)]
    completed = {key for key, pair in before.items() if pair[0]['status'] == 'done'}
    errors, allowed = [], set()
    for identifier in changed:
        old = before[identifier][0] if identifier in before else None
        new = after[identifier][0] if identifier in after else None
        errors.extend(validate_transition(old, new, completed))
        scope_errors, scope = _transition_scope(old, new, identifier, parent)
        errors.extend(scope_errors)
        allowed.update(scope)
    if changed:
        actual = set(filter(None, journal.git(root, 'diff', '--no-ext-diff', '--name-only', '-z', parent, revision).split('\0')))
        if not actual.issubset(allowed):
            errors.append('TASK_SCOPE: task transition commit contains unrelated changes')
    return ['{}: {}'.format(revision, e) for e in errors + validate_snapshot(root, revision)]


def _audit_range(root, base, head, cache):
    key = (base, head)
    if key in cache:
        return cache[key]
"""Independent real-Git oracle for mandatory task implementation scope.

All approvals and products in this module are synthetic temporary fixtures.
No fixture approves or changes the KDD checkout itself.
"""
import hashlib
import json
from pathlib import Path
import sys
import tempfile
import unittest

from tests.test_generated_task_evidence import TaskProject


class PerimeterProject(TaskProject):
    def __init__(self, root):
        super().__init__(root)
        self.write('auxiliary.txt', 'existing unrelated product file\n')
        self.ref = self.commit('Synthetic reviewed baseline with auxiliary file')

    @staticmethod
    def oracle(number):
        return TaskProject.oracle(number) + '''
import os
from pathlib import Path
if os.environ.get('KDD_PERIMETER_PROBE'):
    Path(os.environ['KDD_PERIMETER_PROBE']).write_text('oracle executed', encoding='utf-8')
'''


class PerimeterCase(unittest.TestCase):
    def setUp(self):
        self.area = tempfile.TemporaryDirectory(prefix='kdd-perimeter-oracle-')
        self.addCleanup(self.area.cleanup)
        self.p = PerimeterProject(Path(self.area.name) / 'product')
        self.marker = Path(self.area.name) / 'oracle-ran.txt'
        self.p.env['KDD_PERIMETER_PROBE'] = str(self.marker)
        self.p.create(1)
        started = self.p.act('start', 1, '--assignee', 'synthetic worker')
        self.branch_base = started['task']['branch_base']
        self.p.git('switch', '-q', 'task/TASK-001')
        self.p.write('src/feature1.py', self.p.implementation(1))

    def integrate(self):
        self.tip = self.p.commit('Synthetic implementation')
        self.p.git('switch', '-q', 'main')
        self.p.git('merge', '--no-ff', 'task/TASK-001', '-qm', 'Integrate synthetic task')
        return self.tip

    def assert_scope_rejected(self, *paths):
        before = self.p.snapshot()
        result = self.p.act('finish', 1, check=False)
        self.assertNotEqual(result.returncode, 0, 'finish accepted an out-of-scope implementation')
        output = result.stdout + result.stderr
        self.assertIn('TASK_PERIMETER', output)
        for path in paths:
            self.assertIn(path, output)
        self.assertFalse(self.marker.exists(), 'oracle executed before the scope rejection')
        self.assertEqual(self.p.snapshot(), before, 'scope rejection changed Git state')
        self.assertEqual(list((self.p.root / 'docs/task-evidence').glob('*.json')), [])

    def legacy_close(self, receipt=None, reported_tip=None):
        """Construct an old-format closure using a real passing oracle result."""
        sys.path.insert(0, str(self.p.root / 'scripts'))
        from task_model import render_task
        from validate_contracts import parse_frontmatter
        node = 'knowledge/tasks/TASK-001.md'
        data, body = parse_frontmatter((self.p.root / node).read_text(encoding='utf-8'))
        tested = self.p.git('rev-parse', 'HEAD')
        outcome = self.p.command([sys.executable, '-m', 'unittest', 'tests/test_feature1.py'])
        def digest(content):
            return hashlib.sha256(content.encode('utf-8') if isinstance(content, str) else content).hexdigest()
        def normalized(name):
            return (self.p.root / name).read_bytes().replace(b'\r\n', b'\n').replace(b'\r', b'\n')
        report = {
            'schema_version': 1, 'task_id': 'TASK-001', 'tested_commit': tested,
            'branch_tip': reported_tip or self.tip, 'approved_ref': self.p.ref,
            'contract_sha256': digest(normalized(self.p.contract(1))),
            'target_sha256': digest(normalized('src/feature1.py')),
            'oracle_sha256': digest(normalized('tests/test_feature1.py')),
            'command': 'python -m unittest tests/test_feature1.py', 'runner': 'unittest',
            'exit_code': outcome.returncode, 'passed_tests': 2,
            'stdout': outcome.stdout, 'stderr': outcome.stderr,
            'output_sha256': digest(outcome.stdout + outcome.stderr),
        }
        if receipt is not None:
            report['perimeter'] = receipt
        content = json.dumps(report, ensure_ascii=True, sort_keys=True, indent=2) + '\n'
        evidence = 'docs/task-evidence/TASK-001-' + tested + '.json'
        data.update(status='done', reason='Synthetic historical closure', verified_ref=tested,
                    evidence=evidence, evidence_sha256=digest(content))
        self.p.write(evidence, content)
        self.p.write(node, render_task(data, body))
        return self.p.commit('Synthetic historical closure with actual passing output')

    def audit(self, ranged=True):
        args = ['--base-ref', self.p.ref, '--head-ref', 'HEAD'] if ranged else ['--head-ref', 'HEAD']
        return self.p.command([sys.executable, 'scripts/validate_tasks.py', '--repo-root',
                               str(self.p.root), *args], check=False)


class FinishPerimeterTests(PerimeterCase):
    def test_allowed_implementation_finishes_with_actual_passing_tests(self):
        self.integrate()
        result = self.p.act('finish', 1)
        self.assertEqual(result['task']['status'], 'done')
        report = json.loads((self.p.root / result['task']['evidence']).read_text(encoding='utf-8'))
        self.assertEqual(report['passed_tests'], 2)
        self.assertTrue(self.marker.exists())

    def test_new_receipt_binds_permissions_and_exact_git_revisions(self):
        self.integrate()
        tested = self.p.git('rev-parse', 'HEAD')
        result = self.p.act('finish', 1)
        report = json.loads((self.p.root / result['task']['evidence']).read_text(encoding='utf-8'))
        receipt = report.get('perimeter')
        self.assertIsInstance(receipt, dict, 'new closures need a perimeter receipt')
        for key, value in {'schema_version': 1, 'approved_ref': self.p.ref,
                           'branch_base': self.branch_base, 'branch_tip': self.tip,
                           'tested_commit': tested, 'paths': ['src/feature1.py']}.items():
            self.assertEqual(receipt.get(key), value, key)

    def test_added_file_outside_scope_rejects_before_oracle_without_writes(self):
        self.p.write('src/outside.py', 'unrelated = True\n')
        self.integrate()
        self.assert_scope_rejected('src/outside.py')

    def test_modified_existing_file_outside_scope_rejects_before_oracle(self):
        self.p.write('auxiliary.txt', 'changed outside the contract\n')
        self.integrate()
        self.assert_scope_rejected('auxiliary.txt')

    def test_deleted_file_outside_scope_rejects_before_oracle(self):
