"""Run reviewed quality checks, including opt-in canonical task evidence.

The reviewed runner and Git are trusted. Candidate checks are not sandboxed.
"""
import argparse
from contextlib import contextmanager
import importlib.util
import json
import os
from pathlib import Path, PurePosixPath
import re
import subprocess
import sys
import tempfile


class Rejected(ValueError):
    """An approval condition was not satisfied."""


def git(root, *args):
    result = subprocess.run(['git', '-C', str(root), *args],
                            capture_output=True, timeout=30, check=False)
    if result.returncode:
        raise Rejected('Git operation failed: ' + result.stderr.decode('utf-8', 'replace').strip())
    return result.stdout


def approved_commit(root, reference):
    """Accept only the native, canonical OID of an existing commit object."""
    if not isinstance(reference, str) or not re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', reference):
        raise Rejected('approved_ref must be a canonical full commit OID, not an alias')
    fields = git(root, 'rev-parse', '--show-object-format', '--verify',
                 '--end-of-options', reference + '^{commit}').decode('ascii').splitlines()
    if (len(fields) != 2 or len(reference) != {'sha1': 40, 'sha256': 64}.get(fields[0])
            or fields[1] != reference):
        raise Rejected('approved_ref must identify the canonical commit object')
    return reference


def _object_header(output, offset, spec, allow_missing):
    end = output.find(b'\n', offset)
    if end < 0:
        raise Rejected('Truncated Git batch header')
    header = output[offset:end].split()
    offset = end + 1
    if header and header[-1] == b'missing' and allow_missing:
        return None, offset
    if (len(header) != 3 or header[1] != b'blob'
            or not re.fullmatch(rb'[0-9a-f]{40}|[0-9a-f]{64}', header[0])):
        raise Rejected('Missing or invalid Git blob: ' + spec)
    if not re.fullmatch(rb'[0-9]+', header[2]):
        raise Rejected('Missing or invalid Git blob: ' + spec)
    size = int(header[2])
    if output[offset + size:offset + size + 1] != b'\n':
        raise Rejected('Truncated Git batch body')
    return output[offset:offset + size], offset + size + 1


def _objects(root, specifications, allow_missing=False):
    specs = list(dict.fromkeys(specifications))
    if not specs:
        return {}
    if any(any(c in spec for c in '\r\n\0') for spec in specs):
        raise Rejected('Invalid Git object specification')
    result = subprocess.run(['git', '-C', str(root), 'cat-file', '--batch'],
                            input=('\n'.join(specs) + '\n').encode('utf-8'),
                            capture_output=True, timeout=30, check=False)
    if result.returncode:
        raise Rejected('Git batch could not complete')
    values, offset = {}, 0
    for spec in specs:
        values[spec], offset = _object_header(result.stdout, offset, spec, allow_missing)
    if offset != len(result.stdout):
        raise Rejected('Unexpected Git batch output')
    return values


def safe_path(root, value):
    if not isinstance(value, str) or not value or any(c in value for c in '\\\x00:*?[]\r\n'):
        raise Rejected('Invalid exact relative path: ' + repr(value))
    path = PurePosixPath(value)
    if path.is_absolute() or any(part in ('', '.', '..') for part in value.split('/')):
        raise Rejected('Invalid relative path: ' + repr(value))
    local = root.joinpath(*path.parts)
    if not local.resolve().is_relative_to(root):
        raise Rejected('Path escapes repository: ' + value)
    return local


def strings(value, label, nonempty=False):
    if not isinstance(value, list) or (nonempty and not value):
        raise Rejected('Expected list: ' + label)
    if any(not isinstance(item, str) or not item.strip() or '\x00' in item for item in value):
        raise Rejected('Expected nonempty strings: ' + label)
    return value


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise Rejected('Duplicate JSON key: ' + key)
        result[key] = value
    return result


TASK_MODULES = ('validate_tasks.py', 'task_git.py', 'task_model.py',
                'task_evidence.py', 'validate_contracts.py')


def _generated_entry(entry, identifiers, protected):
    if not isinstance(entry, dict) or set(entry) != {'task_id', 'contract'}:
        raise Rejected('Invalid generated task evidence entry')
    identifier, contract = entry['task_id'], entry['contract']
    if not isinstance(identifier, str) or not re.fullmatch(r'TASK-[0-9]{3,}', identifier):
        raise Rejected('Invalid generated task ID')
    if identifier in identifiers:
        raise Rejected('Duplicate generated task ID')
    identifiers.add(identifier)
    if not isinstance(contract, str) or not re.fullmatch(r'knowledge/contracts/[\w.-]+\.md', contract):
        raise Rejected('Invalid generated task contract')
    if contract not in protected:
        raise Rejected('Generated task contract must be protected')


def _generated_policy(data):
    if 'generated_task_evidence' not in data:
        return
    entries = data['generated_task_evidence']
    if not isinstance(entries, list) or not entries:
        raise Rejected('generated_task_evidence must be a nonempty list')
    identifiers = set()
    for entry in entries:
        _generated_entry(entry, identifiers, data['protected'])
    required = {'scripts/' + name for name in TASK_MODULES}
    if not required.issubset(data['protected']):
        raise Rejected('All canonical task validators must be protected')


def _check_policy(check, names, kinds):
    if not isinstance(check, dict) or set(check) != {'name', 'kind', 'argv', 'timeout'}:
        raise Rejected('Invalid check schema')
    strings([check['name'], check['kind']], 'check name/kind', True)
    if check['name'] in names:
        raise Rejected('Duplicate check name: ' + check['name'])
    names.add(check['name'])
    kinds.add(check['kind'])
    strings(check['argv'], 'argv', True)
    if type(check['timeout']) is not int or not 0 < check['timeout'] <= 3600:
        raise Rejected('timeout must be an integer in 1..3600')


def validate_policy(root, data):
    fields = {'protected', 'implementation', 'pm', 'required_kinds', 'checks'}
    if not isinstance(data, dict) or set(data) not in (fields, fields | {'generated_task_evidence'}):
        raise Rejected('Policy fields must be: ' + ', '.join(sorted(fields)))
    for field in ('protected', 'implementation', 'pm'):
        for name in strings(data[field], field, field == 'protected'):
            safe_path(root, name)
    required = strings(data['required_kinds'], 'required_kinds', True)
    if not {'functional', 'adversarial'}.issubset(required):
        raise Rejected('functional and adversarial kinds are required')
    if not isinstance(data['checks'], list) or not data['checks']:
        raise Rejected('checks must be a nonempty list')
    names, kinds = set(), set()
    for check in data['checks']:
        _check_policy(check, names, kinds)
    if not set(required).issubset(kinds):
        raise Rejected('Required kind has no check')
    _generated_policy(data)
    return data


def normalized(content):
    return content.replace(b'\r\n', b'\n').replace(b'\r', b'\n')


def changed_paths(root, commit):
    names = set()
    commands = [
        ('diff', '--no-ext-diff', '--no-renames', '--name-only', '-z', commit, '--'),
        ('diff', '--no-ext-diff', '--no-renames', '--name-only', '-z', '--cached', commit, '--'),
        ('diff', '--no-ext-diff', '--no-renames', '--name-only', '-z', '--'),
        ('ls-files', '--others', '--exclude-standard', '-z'),
    ]
    for command in commands:
        names.update(p.decode('utf-8') for p in git(root, *command).split(b'\x00') if p)
    return names


_TASK_AUDIT = """import json,sys
from pathlib import Path
sys.path.insert(0,sys.argv[1])
import task_git as journal
from validate_contracts import parse_frontmatter
from validate_tasks import validate_range
root,approved,head=Path(sys.argv[2]),sys.argv[3],sys.argv[4]
policy=json.loads(sys.stdin.read())
tasks=journal.read_tasks(root,head)
artifacts,nodes=[],[]
for entry in policy['generated_task_evidence']:
    contract=entry['contract']
    metadata,_=parse_frontmatter(journal.blob(root,approved,contract))
    if not isinstance(metadata,dict) or metadata.get('tests') not in policy['protected']:
        raise SystemExit('Generated task oracle must be protected')
    identifier=entry['task_id']
    node='knowledge/tasks/'+identifier+'.md'
    task=tasks.get(identifier)
    if task is not None:
        nodes.append(node)
        if task['contract']!=contract:
            raise SystemExit('Generated task contract mismatch')
        if task['status']=='done':
            artifacts.append(task['evidence'])
chain=journal.git(root,'rev-list','--first-parent','--reverse',head).splitlines()
findings=validate_range(root,chain[0],head)
if findings:
    raise SystemExit('Generated task history rejected: '+'; '.join(findings))
print(json.dumps({'artifacts':artifacts,'nodes':nodes}))
"""


def _task_manifest(root, commit, policy, approved, cache):
    head = git(root, 'rev-parse', '--verify', 'HEAD^{commit}').decode('ascii').strip()
    if head in cache:
        return cache[head]
    with tempfile.TemporaryDirectory(prefix='kdd-frozen-task-audit-') as directory:
        bundle = Path(directory)
        if bundle.resolve().is_relative_to(root):
            raise Rejected('Trusted task bundle must be outside the checkout')
        for name in TASK_MODULES:
            (bundle / name).write_bytes(approved['scripts/' + name])
        env = dict(os.environ, PYTHONDONTWRITEBYTECODE='1', PYTHONUTF8='1')
        for name in ('PYTHONPATH', 'GIT_DIR', 'GIT_WORK_TREE', 'GIT_INDEX_FILE', 'GIT_COMMON_DIR'):
            env.pop(name, None)
        result = subprocess.run([sys.executable, '-I', '-c', _TASK_AUDIT,
                                 str(bundle), str(root), commit, head],
                                input=json.dumps(policy), capture_output=True, text=True,
                                encoding='utf-8', env=env, timeout=180, check=False)
    if result.returncode:
        raise Rejected('Task evidence audit failed: ' + result.stderr.strip())
    try:
        report = json.loads(result.stdout)
        artifacts, nodes = report['artifacts'], report['nodes']
        names = artifacts + nodes
        blobs = _objects(root, [head + ':' + name for name in names])
        manifest = {name: blobs[head + ':' + name] for name in names}
    except (ValueError, KeyError, TypeError) as exc:
        raise Rejected('Invalid trusted task manifest') from exc
    cache[head] = (artifacts, manifest)
    return cache[head]


def _generated_integrity(root, commit, policy, approved, cache):
    if 'generated_task_evidence' not in policy:
        return set()
    artifacts, manifest = _task_manifest(root, commit, policy, approved, cache)
    indices = _objects(root, [':' + name for name in manifest], allow_missing=True)
    for name, expected in manifest.items():
        path = safe_path(root, name)
        if not path.is_file() or path.is_symlink():
            raise Rejected('Committed task artifact missing: ' + name)
        work, index = path.read_bytes(), indices[':' + name]
        if name not in artifacts:
            work = normalized(work)
            index = normalized(index) if index is not None else None
        if work != expected or index != expected:
            raise Rejected('Task evidence or node differs from committed HEAD: ' + name)
    declared = {'knowledge/tasks/' + item['task_id'] + '.md'
                for item in policy['generated_task_evidence']}
    for name in declared - manifest.keys():
        if safe_path(root, name).exists():
            raise Rejected('Generated task node must be committed: ' + name)
    return set(artifacts)


def _protected_integrity(root, approved):
    indices = _objects(root, [':' + name for name in approved], allow_missing=True)
    for name, content in approved.items():
        path = safe_path(root, name)
        if not path.is_file() or path.is_symlink():
            raise Rejected('Protected file missing or symlink: ' + name)
        if normalized(path.read_bytes()) != normalized(content):
            raise Rejected('Protected file changed: ' + name)
        index = indices[':' + name]
        if index is None or normalized(index) != normalized(content):
            raise Rejected('Protected index changed: ' + name)


def integrity(root, commit, policy, approved, cache=None):
    for field in ('protected', 'implementation', 'pm'):
        for name in policy[field]:
            safe_path(root, name)
    _protected_integrity(root, approved)
    generated = _generated_integrity(root, commit, policy, approved,
                                     cache if cache is not None else {})
    allowed = set(policy['implementation']) | set(policy['pm']) | generated
    for name in changed_paths(root, commit):
        safe_path(root, name)
        if name not in allowed and name not in approved:
            raise Rejected('Outside approved perimeter: ' + name)


@contextmanager
def _approved_process_runner(root, commit, content):
    name = 'scripts/process_tree.py'
    entry = git(root, 'ls-tree', commit, '--', name)
    header, separator, path = entry.rstrip(b'\n').partition(b'\t')
    fields = header.split()
    if (not separator or path != name.encode('ascii') or len(fields) != 3
            or fields[0] not in (b'100644', b'100755') or fields[1] != b'blob'):
        raise Rejected('Approved process helper must be a regular Git file')
    with tempfile.TemporaryDirectory(prefix='kdd-approved-quality-process-') as directory:
        helper = Path(directory) / 'process_tree.py'
        if helper.resolve().is_relative_to(root):
            raise Rejected('Approved process helper must be outside the checkout')
        helper.write_bytes(content)
        spec = importlib.util.spec_from_file_location('_kdd_approved_quality_process', helper)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        yield module.run


def _checks(root, commit, policy, approved, run):
    cache = {}
    integrity(root, commit, policy, approved, cache)
    for iteration in (1, 2):
        for check in policy['checks']:
            print('RUN %s/2 %s [%s]' % (iteration, check['name'], check['kind']), flush=True)
            try:
                result = run(check['argv'], cwd=root, timeout=check['timeout'],
                             shell=False)
            finally:
                integrity(root, commit, policy, approved, cache)
            if result.returncode:
                raise Rejected('Check failed: %s (exit %s)' % (check['name'], result.returncode))


def approve(root, policy_path, reference):
    root = root.resolve(strict=True)
    actual = Path(git(root, 'rev-parse', '--show-toplevel').decode().strip()).resolve()
    if actual != root:
        raise Rejected('repo-root must be the Git repository root')
    safe_path(root, policy_path)
    commit = approved_commit(root, reference)
    raw = git(root, 'show', commit + ':' + policy_path)
    policy = validate_policy(root, json.loads(raw, object_pairs_hook=unique_object))
    helper = commit + ':scripts/process_tree.py'
    objects = _objects(root, [commit + ':' + name for name in policy['protected']] + [helper])
    approved = {name: objects[commit + ':' + name] for name in policy['protected']}
    approved[policy_path] = raw
    with _approved_process_runner(root, commit, objects[helper]) as run:
        _checks(root, commit, policy, approved, run)
    print('PASS quality: integrity, perimeter and all checks verified twice', flush=True)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo-root', default='.')
    parser.add_argument('--policy', required=True)
    parser.add_argument('--approved-ref', required=True)
    args = parser.parse_args()
    try:
        approve(Path(args.repo_root), args.policy, args.approved_ref)
    except (ValueError, OSError, RuntimeError, subprocess.SubprocessError) as error:
        print('REJECT quality: ' + str(error), file=sys.stderr)
        return 1
    return 0


if __name__ == '__main__':
    sys.exit(main())
#!/usr/bin/env python3
"""Run small deterministic Python mutants against one frozen test command."""

import argparse
import ast
import copy
import os
from pathlib import Path
import shutil
import shlex
import stat
import subprocess
import sys
import tempfile

from validate_contracts import parse_frontmatter, relative_artifact
from process_tree import run as run_process


class _FirstMutation(ast.NodeTransformer):
    def __init__(self, operator):
        self.operator = operator
        self.changed = False

    def visit_Constant(self, node):
        if self.operator == "invert-bool" and not self.changed and isinstance(node.value, bool):
            self.changed = True
            return ast.copy_location(ast.Constant(value=not node.value), node)
        return self.generic_visit(node)

    def visit_Compare(self, node):
        if self.operator == "flip-comparison" and not self.changed and node.ops:
            flips = {ast.Eq: ast.NotEq, ast.NotEq: ast.Eq,
                     ast.Lt: ast.GtE, ast.GtE: ast.Lt,
                     ast.Gt: ast.LtE, ast.LtE: ast.Gt}
            operator_type = type(node.ops[0])
            if operator_type in flips:
                node = copy.deepcopy(node)
                node.ops[0] = flips[operator_type]()
                self.changed = True
                return node
        return self.generic_visit(node)

    def visit_If(self, node):
        if self.operator == "negate-branch" and not self.changed:
            node = copy.deepcopy(node)
            node.test = ast.UnaryOp(op=ast.Not(), operand=node.test)
            self.changed = True
            return node
        return self.generic_visit(node)


def mutation_sources(source):
    results = []
    tree = ast.parse(source)
    for operator in ("invert-bool", "flip-comparison", "negate-branch"):
        mutant = _FirstMutation(operator)
        mutated_tree = mutant.visit(copy.deepcopy(tree))
        if mutant.changed:
            results.append({"operator": operator,
                            "source": ast.unparse(ast.fix_missing_locations(mutated_tree)) + "\n"})
    return results


def _command(value):
    try:
        tokens = shlex.split(value, posix=os.name != "nt")
        if os.name == 'nt':
            tokens = [t[1:-1] if len(t) > 1 and t[0] == t[-1] and t[0] in "\"'" else t for t in tokens]
        return tokens
    except ValueError as exc:
        raise ValueError("test_command invalido: {}".format(exc)) from exc


def _copy_inputs(root, destination):
    agents = os.path.abspath(os.path.join(root, '.agents'))
    def ignore(directory, names):
        excluded = {name for name in names if name in ('.git', '__pycache__')
                    or name.endswith(('.pyc', '.pyo'))}
        if os.path.abspath(directory) == agents:
            excluded.add('logs')
        return excluded
    shutil.copytree(root, destination, ignore=ignore)


def _execute(command, directory, timeout):
    try:
        completed = run_process(command, cwd=directory, capture_output=True, timeout=timeout)
        return {'exit_code': completed.returncode, 'timeout': False}
    except subprocess.TimeoutExpired:
        return {'exit_code': None, 'timeout': True}
    except (OSError, ValueError, subprocess.SubprocessError) as exc:
        return {'exit_code': None, 'timeout': False, 'error': str(exc)}


def _control(command, root, destination, stage, timeout):
    try:
        _copy_inputs(root, destination)
        result = _execute(command, destination, timeout)
    except (OSError, ValueError) as exc:
        result = {'exit_code': None, 'timeout': False, 'error': str(exc)}
    return dict(result, stage=stage,
                status='PASS' if result['exit_code'] == 0 else 'INCONCLUSIVE')


def _target_path(root, relative):
    if relative_artifact(str(root), relative) is None:
        raise ValueError('MUTATION_PATH: exact relative target inside the project required')
    path = root
    for part in relative.split('/'):
        path = path / part
        try:
            info = path.lstat()
        except FileNotFoundError:
            if not relative.lower().endswith('.py'):
                return root / relative
            raise
        if stat.S_ISLNK(info.st_mode) or getattr(info, 'st_file_attributes', 0) & 0x400:
            raise ValueError('MUTATION_PATH: target aliases and reparse points are unsupported')
    if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
        raise ValueError('MUTATION_PATH: target must be a regular file with one link')
    return path


def _reject(reason):
    return dict(status='REJECT', reason=reason, detected=0, survived=0,
                inconclusive=0, mutants=[], controls=[])


def audit_contract(contract_path, repo_root, timeout=120):
    with open(contract_path, "r", encoding="utf-8") as fh:
        data, _body = parse_frontmatter(fh.read())
    if not isinstance(data, dict):
        return _reject('MUTATION_INPUT: task contract metadata required')
    target_rel = data.get("target", "")
    try:
        root = Path(repo_root).resolve(strict=True)
        target = _target_path(root, target_rel)
    except (OSError, ValueError) as error:
        return _reject(str(error))
    if not target_rel.lower().endswith(".py"):
        return {"status": "SKIP", "reason": "target no Python", "detected": 0,
                "survived": 0, "inconclusive": 0, "mutants": []}
    with open(target, "r", encoding="utf-8") as fh:
        source = fh.read()
    mutants = mutation_sources(source)
    if not mutants:
        return {"status": "SKIP", "reason": "sin operador aplicable", "detected": 0,
                "survived": 0, "inconclusive": 0, "mutants": []}
    command = _command(data["test_command"])
    outcomes, controls = [], []
    with tempfile.TemporaryDirectory(prefix="kdd-mutant-") as temporary:
        if Path(temporary).resolve().is_relative_to(root):
            return _reject('MUTATION_PATH: mutation copies must be outside the project')
        for stage in ('original', 'copy'):
            control = _control(command, root, os.path.join(temporary, stage), stage, timeout)
            controls.append(control)
            if control['status'] != 'PASS':
                return {'status': 'FAIL', 'detected': 0, 'survived': 0, 'inconclusive': 0,
                        'mutants': [], 'controls': controls}
        for index, mutant in enumerate(mutants):
            directory = os.path.join(temporary, 'mutant-' + str(index))
            try:
                _copy_inputs(root, directory)
                destination = _target_path(Path(directory).resolve(strict=True), target_rel)
                with open(destination, "w", encoding="utf-8") as fh:
                    fh.write(mutant['source'])
                result = _execute(command, directory, timeout)
            except (OSError, ValueError) as exc:
                result = {'exit_code': None, 'timeout': False, 'error': str(exc)}
            status = ('INCONCLUSIVE' if result['exit_code'] is None else
                      'DETECTED' if result['exit_code'] else 'SURVIVED')
            outcomes.append({"operator": mutant["operator"], "status": status})
    counts = {status: sum(item["status"] == status for item in outcomes)
              for status in ("DETECTED", "SURVIVED", "INCONCLUSIVE")}
    return {"status": "PASS" if not counts["SURVIVED"] and not counts["INCONCLUSIVE"] else "FAIL",
            "detected": counts["DETECTED"], "survived": counts["SURVIVED"],
            "inconclusive": counts["INCONCLUSIVE"], "mutants": outcomes, 'controls': controls}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("contract")
    parser.add_argument("--repo-root", default=".")
    parser.add_argument("--strict", action="store_true")
    args = parser.parse_args(argv)
    try:
        result = audit_contract(args.contract, args.repo_root)
    except (OSError, ValueError, KeyError) as error:
        result = _reject(str(error))
    if result['status'] == 'REJECT':
        print('REJECT mutation: ' + result.get('reason', 'invalid contract'))
        return 2
    for control in result.get('controls', []):
        print('control {}: {} exit={} timeout={}'.format(
            control['stage'], control['status'], control['exit_code'], control['timeout']))
    for mutant in result.get("mutants", []):
        print("{}: {}".format(mutant["operator"], mutant["status"]))
    print("mutation-audit: {} detected, {} survived, {} inconclusive".format(
        result["detected"], result["survived"], result["inconclusive"]))
    return 1 if args.strict and result["status"] == "FAIL" else 0


if __name__ == "__main__":
    sys.exit(main())
"""Auditor de seals debiles (Contrato: seal-audit).

Herramienta ADVISORY: detecta oraculos congelados que el sello
(``tests_sha256``) certifica como integros pero que no pueden fallar --
sin asserts reales (``assert True`` no cuenta), sin funciones de test, o
sin referenciar jamas al target. El sello garantiza integridad, no fuerza;
este auditor reporta la ausencia mecanica de fuerza. La calidad semantica
de un assert no-trivial queda fuera (trabajo de mutation testing).

Solo LEE archivos. Sin subprocess, sin red, sin LLM. Deteccion por ``ast``
(stdlib), nunca regex sobre el codigo. ASCII puro (lo audita
``lint_ascii``). Ver ``knowledge/contracts/seal-audit.md``.

API (congelada por ``tests/test_audit_seals.py``):
  Reglas (constantes str): WEAK_TESTS_MISSING, WEAK_TESTS_EMPTY,
    WEAK_TESTS_UNPARSEABLE, WEAK_NO_TEST_FUNCTIONS, WEAK_NO_ASSERTS,
    WEAK_TARGET_UNREFERENCED.
  ``audit_contract(contract_path, repo_root) -> list[dict]`` -- findings
    ``{'contract','rule','msg'}`` de UN contrato (lista vacia = sano).
  ``audit_seals(contracts_dir='knowledge/contracts', repo_root='.') ->
    {'findings': [...], 'checked': int}`` -- recorre ``*.md`` (salta
    ``TEMPLATE-*``), findings ordenados por (contract, rule).
  ``main(argv) -> int`` -- argv estilo ``sys.argv``; posicional opcional
    contracts_dir, flags ``--repo-root DIR`` y ``--strict``. Sin
    ``--strict`` SIEMPRE 0 (advisory); con ``--strict`` 1 si hay findings.
"""

import ast
import os
import sys

from validate_contracts import parse_frontmatter

WEAK_TESTS_MISSING = 'WEAK_TESTS_MISSING'
WEAK_TESTS_EMPTY = 'WEAK_TESTS_EMPTY'
WEAK_TESTS_UNPARSEABLE = 'WEAK_TESTS_UNPARSEABLE'
WEAK_NO_TEST_FUNCTIONS = 'WEAK_NO_TEST_FUNCTIONS'
WEAK_NO_ASSERTS = 'WEAK_NO_ASSERTS'
WEAK_TARGET_UNREFERENCED = 'WEAK_TARGET_UNREFERENCED'


def _finding(contract, rule, msg):
    """Construye un finding de un contrato."""
    return {'contract': contract, 'rule': rule, 'msg': msg}


def _contract_targets(data):
    """Devuelve (tests, target) o None si el contrato no es auditable.

    No es auditable si no hay frontmatter o faltan las claves tests/target
    (la estructura la vigila validate_contracts, no este auditor).
    """
    if not data:
        return None
    tests = data.get('tests')
    target = data.get('target')
    if not isinstance(tests, str) or not isinstance(target, str):
        return None
    return tests, target


def _read_tests(tests_path):
    """Devuelve (status, src). status in {'missing','empty','unparseable','ok'}.

    Nunca lanza: archivo ausente o ilegible por I/O -> 'missing'; presente
    pero no decodificable como utf-8 -> 'unparseable' (mismo significado que
    un SyntaxError del AST). AUDIT-05 H-3.
    """
    if not os.path.isfile(tests_path):
        return 'missing', ''
    try:
        with open(tests_path, 'r', encoding='utf-8') as fh:
            src = fh.read()
    except UnicodeDecodeError:
        return 'unparseable', ''
    except OSError:
        return 'missing', ''
    if not src.strip():
        return 'empty', ''
    return 'ok', src


def _has_test_functions(tree):
    """True si hay FunctionDef/AsyncFunctionDef cuyo nombre empieza con test."""
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if node.name.startswith('test'):
                return True
    return False


def _is_real_assert(node):
    """True si el nodo es un assert real.

    ast.Assert cuyo test NO es ast.Constant (``assert True`` no cuenta), o
    ast.Call cuyo func es ast.Attribute con attr que empieza con 'assert'
    (cubre self.assertEqual, assertRaises, etc.).
    """
    if isinstance(node, ast.Assert):
        return not isinstance(node.test, ast.Constant)
    if isinstance(node, ast.Call):
        func = node.func
        if isinstance(func, ast.Attribute) and func.attr.startswith('assert'):
            return True
    return False


def _has_real_asserts(tree):
    """True si el arbol contiene al menos un assert real."""
    for node in ast.walk(tree):
        if _is_real_assert(node):
            return True
    return False


def _py_findings(tree, contract, target_stem, needs_ref):
    """Findings del analisis AST de un tests file Python.

    No hay cortocircuito entre estas reglas: pueden coexistir.
    """
    findings = []
    if not _has_test_functions(tree):
        findings.append(_finding(contract, WEAK_NO_TEST_FUNCTIONS,
                                 'no test functions in tests file'))
    if not _has_real_asserts(tree):
        findings.append(_finding(contract, WEAK_NO_ASSERTS,
                                 'no real asserts in tests file'))
    if needs_ref:
        findings.append(_finding(contract, WEAK_TARGET_UNREFERENCED,
                                 'target stem not in tests source: '
                                 + target_stem))
    findings.sort(key=lambda f: f['rule'])
    return findings


def _audit(contract_path, repo_root):
    """Nucleo: devuelve (auditable, findings).

    auditable=False significa que el contrato no tiene frontmatter o le
    faltan las claves tests/target -> no cuenta en ``checked`` y no genera
    findings. Nunca lanza: el problema es un finding o (False, []).
    """
    contract = os.path.basename(contract_path)
    try:
        with open(contract_path, 'r', encoding='utf-8') as fh:
            text = fh.read()
    except (OSError, UnicodeDecodeError):
        # contrato no-utf8 (UnicodeDecodeError es ValueError, no OSError):
        # no auditable, sin crash. AUDIT-05 H-3.
        return False, []
    data, _body = parse_frontmatter(text)
    targets = _contract_targets(data)
    if targets is None:
        return False, []
    tests_rel, target_rel = targets
    status, src = _read_tests(os.path.join(repo_root, tests_rel))
    if status == 'missing':
        return True, [_finding(contract, WEAK_TESTS_MISSING,
                               'tests file not found: ' + tests_rel)]
    if status == 'empty':
        return True, [_finding(contract, WEAK_TESTS_EMPTY,
                               'tests file empty: ' + tests_rel)]
    if status == 'unparseable':
        return True, [_finding(contract, WEAK_TESTS_UNPARSEABLE,
                               'tests file not utf-8: ' + tests_rel)]
    target_stem = os.path.splitext(os.path.basename(target_rel))[0]
    is_self = os.path.normpath(tests_rel) == os.path.normpath(target_rel)
    needs_ref = (not is_self) and (target_stem not in src)
    if os.path.splitext(tests_rel)[1] != '.py':
        # Tests no-Python: el analisis AST es Python-only.
        if needs_ref:
            return True, [_finding(contract, WEAK_TARGET_UNREFERENCED,
                                   'target stem not in tests source: '
                                   + target_stem)]
        return True, []
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return True, [_finding(contract, WEAK_TESTS_UNPARSEABLE,
                               'tests file not parseable: ' + tests_rel)]
